/**
 * Control positivo para los tests de decodificación de QR.
 *
 * Matriz de módulos de un código QR CORRECTO, nivel M, generada con
 * `qrcode-generator@2.0.4` (port del encoder de Kazuhiko Arase, conforme a
 * ISO/IEC 18004). Se versiona como dato, no como dependencia: su única función es
 * demostrar que el rasterizador y el decodificador de `tests/helpers/qr.ts`
 * funcionan, de modo que un fallo del generador del repositorio no pueda
 * atribuirse al método de prueba.
 *
 * El contenido es la URL de cotejo del ejemplo §8.1 de la especificación del QR
 * de la AEAT (v0.5.0), con sus 4 parámetros reglamentarios.
 *
 * Versión 7 (45×45 módulos) para 118 caracteres en modo byte.
 */

export const QR_CONTROL_URL =
  'https://prewww2.aeat.es/wlpl/TIKE-CONT/ValidarQR?nif=89890001K&numserie=12345678%2FG33&fecha=01-01-2024&importe=241.40';

